package com.petcare.backend.controller;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper;import com.petcare.backend.dto.common.PageResponse;import com.petcare.backend.dto.pet.request.*;import com.petcare.backend.dto.pet.response.*;import com.petcare.backend.security.UserPrincipal;import com.petcare.backend.service.PetService;import jakarta.validation.Validator;import java.util.List;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.*;
@ExtendWith(MockitoExtension.class) @MockitoSettings(strictness=org.mockito.quality.Strictness.LENIENT) class PetControllerTest{
 @Mock PetService service;@Mock ObjectMapper mapper;@Mock Validator validator;@Mock UserPrincipal principal;PetController c;@BeforeEach void init(){c=new PetController(service,mapper,validator);when(principal.getId()).thenReturn(1L);} @Test void jsonAndReadMethodsDelegate(){PetResponse p=mock(PetResponse.class);CreatePetRequest create=new CreatePetRequest();UpdatePetRequest update=new UpdatePetRequest();when(service.createPet(principal,create)).thenReturn(p);when(service.getPetById(principal,2L)).thenReturn(p);when(service.updatePet(principal,2L,update)).thenReturn(p);when(service.archivePet(principal,2L)).thenReturn(p);assertThat(c.createPet(principal,create).getBody().getData()).isSameAs(p);assertThat(c.getPet(principal,2L).getBody().getData()).isSameAs(p);assertThat(c.updatePet(principal,2L,update).getBody().getData()).isSameAs(p);assertThat(c.archivePet(principal,2L).getBody().getData()).isSameAs(p);c.deletePet(principal,2L);verify(service).deletePet(principal,2L);}
 @Test void coParentAndInvitationMethodsDelegate(){var cp=mock(CoParentResponse.class);var inv=mock(CoParentInvitationResponse.class);var page=PageResponse.<CoParentInvitationResponse>builder().content(List.of()).build();when(service.getCoParents(principal,2L)).thenReturn(List.of(cp));when(service.createCoParentInvitation(eq(1L),eq(2L),any())).thenReturn(inv);when(service.updateCoParentRole(eq(1L),eq(2L),eq(3L),any())).thenReturn(cp);when(service.getIncomingInvitations(1L,0,20)).thenReturn(page);when(service.getOutgoingInvitations(1L,0,20)).thenReturn(page);when(service.getInvitation(1L,3L)).thenReturn(inv);when(service.acceptCoParentInvitation(1L,3L)).thenReturn(inv);when(service.declineCoParentInvitation(1L,3L)).thenReturn(inv);when(service.revokeCoParentInvitation(1L,3L)).thenReturn(inv);assertThat(c.getCoParents(principal,2L).getBody().getData()).contains(cp);assertThat(c.incoming(principal,0,20).getBody().getData()).isSameAs(page);assertThat(c.outgoing(principal,0,20).getBody().getData()).isSameAs(page);assertThat(c.invitation(principal,3L).getBody().getData()).isSameAs(inv);assertThat(c.accept(principal,3L).getBody().getData()).isSameAs(inv);assertThat(c.decline(principal,3L).getBody().getData()).isSameAs(inv);assertThat(c.revoke(principal,3L).getBody().getData()).isSameAs(inv);c.removeCoParent(principal,2L,3L);verify(service).removeCoParent(1L,2L,3L);}
 @Test void multipartEndpoints_ParseAndDelegate() throws Exception {CreatePetRequest create=new CreatePetRequest();UpdatePetRequest update=new UpdatePetRequest();org.springframework.web.multipart.MultipartFile avatar=mock(org.springframework.web.multipart.MultipartFile.class);when(mapper.readValue("create",CreatePetRequest.class)).thenReturn(create);when(mapper.readValue("update",UpdatePetRequest.class)).thenReturn(update);when(validator.validate(any())).thenReturn(java.util.Set.of());PetResponse p=mock(PetResponse.class);when(service.createPet(1L,create,avatar)).thenReturn(p);when(service.updatePet(1L,2L,update,avatar)).thenReturn(p);assertThat(c.createPetMultipart(principal,"create",avatar).getBody().getData()).isSameAs(p);assertThat(c.updatePetMultipart(principal,2L,"update",avatar).getBody().getData()).isSameAs(p);}
}
